package br.com.mecaniQA.api.Mappers;
import java.sql.*; import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Enums.*;
public class ItemPedidoResultSetMapper implements ResultSetMapper<ItemPedido>{public ItemPedido map(ResultSet r)throws SQLException{Cliente c=new Cliente();Veiculo v=new Veiculo();OrdemServico os=OrdemServico.builder().comCliente(c).comVeiculo(v).comDescricaoProblema("Pedido carregado do banco").comStatus(StatusOrdemServico.ABERTO).build();PedidoPecas pedido=new PedidoPecas(os,StatusPedidoPecas.ORCANDO);pedido.setNumeroPedido(r.getLong("numero_pedido"));String nome="Item carregado";Pecas p=new Pecas(nome,null,0,null,0,0,null);p.setCodigoUnico(r.getLong("codigo_peca"));ItemPedido x=new ItemPedido(pedido,p,r.getInt("quantidade"),r.getDouble("preco_unitario"));x.setIdItem(r.getLong("id_item"));x.setObservacoes(r.getString("observacoes"));return x;}}
